const input = $input.first().json;
const body = input.body || input;

const now = new Date();
const createdAt = now.toISOString();

function clean(value) {
  return String(value ?? '').trim();
}

function titleCase(value) {
  return clean(value)
    .toLowerCase()
    .replace(/\b\w/g, char => char.toUpperCase());
}

const clientName = titleCase(body.clientName || body.name || body.contactName);
const clientEmail = clean(body.clientEmail || body.email).toLowerCase();
const company = titleCase(body.company || body.businessName || clientName);
const service = clean(body.service || body.serviceType || body.projectType || 'General project');
const packageName = clean(body.package || body.plan || 'Standard');
const budget = Number(body.budget || body.amount || 0);
const startDate = clean(body.startDate || body.projectStartDate);
const projectManager = clean(body.projectManager || body.owner);
const notes = clean(body.notes || body.message || body.requirements);

if (!clientName) throw new Error('clientName is required.');
if (!clientEmail) throw new Error('clientEmail is required.');
if (!clientEmail.includes('@')) throw new Error('clientEmail must be a valid email address.');

const emailPrefix = clientEmail.split('@')[0].replace(/[^a-z0-9]/gi, '').slice(0, 8).toUpperCase();
const stamp = Date.now().toString().slice(-6);
const clientId = clean(body.clientId) || `CL-${emailPrefix}-${stamp}`;
const projectId = clean(body.projectId) || `PR-${emailPrefix}-${stamp}`;

return [{
  json: {
    createdAt,
    clientId,
    projectId,
    clientName,
    clientEmail,
    company,
    service,
    packageName,
    budget,
    startDate,
    projectManager,
    notes,
    source: clean(body.source || 'Webhook')
  }
}];

const client = $('Validate Client Intake').first().json;
const existingRows = $('Read Existing Clients').all().map(item => item.json);
const configRows = $input.all().map(item => item.json);

const config = Object.fromEntries(
  configRows
    .filter(row => row.Key || row.key)
    .map(row => [String(row.Key || row.key).trim(), String(row.Value || row.value || '').trim()])
);

const defaultProjectManager = config.defaultProjectManager || 'user@example.com';
const defaultKickoffDays = Number(config.defaultKickoffDays || 3);
const rushKickoffDays = Number(config.rushKickoffDays || 1);
const vipServices = String(config.vipServices || 'enterprise,retainer,seo')
  .split(',')
  .map(item => item.trim().toLowerCase())
  .filter(Boolean);

const duplicate = existingRows.find(row =>
  String(row['Client Email'] || row.Email || '').toLowerCase().trim() === client.clientEmail &&
  !['closed', 'inactive', 'cancelled'].includes(String(row.Status || '').toLowerCase())
);

const missing = [];
if (!client.company) missing.push('Company');
if (!client.service) missing.push('Service');
if (!client.packageName) missing.push('Package');
if (!client.startDate) missing.push('Start Date');
if (!client.projectManager) missing.push('Project Manager');

const serviceLower = client.service.toLowerCase();
const packageLower = client.packageName.toLowerCase();
const isVipService = vipServices.some(keyword => serviceLower.includes(keyword) || packageLower.includes(keyword));
const isHighValue = client.budget >= Number(config.highValueBudget || 1000);
const isRush = client.startDate ? ((new Date(client.startDate) - new Date()) / 86400000 <= 3) : false;

let priority = 'Normal';
if (isHighValue || isVipService) priority = 'High';
if (isRush) priority = 'Rush';

const kickoffDays = isRush ? rushKickoffDays : defaultKickoffDays;
const kickoffTarget = new Date(Date.now() + kickoffDays * 86400000).toISOString().slice(0, 10);
const owner = client.projectManager || defaultProjectManager;

const checklist = [
  'Confirm signed agreement and scope',
  'Collect brand, login, and access assets',
  'Schedule kickoff call',
  'Create project workspace and assign owner',
  'Confirm timeline, milestones, and communication channel',
  'Send first-week delivery plan'
];

const riskReasons = [];
if (duplicate) riskReasons.push(`Active client already exists: ${duplicate['Client ID'] || duplicate['Client Email']}`);
if (missing.length) riskReasons.push(`Missing information: ${missing.join(', ')}`);
if (isRush) riskReasons.push('Rush start date');
if (isHighValue) riskReasons.push('High-value client');
if (isVipService) riskReasons.push('VIP service or package');

const needsAttention = riskReasons.length > 0;
const riskLevel = duplicate ? 'Duplicate Review' : (isRush || isHighValue || isVipService ? 'High' : (missing.length ? 'Medium' : 'Low'));

const handoffSummary = [
  `Client: ${client.clientName} (${client.company})`,
  `Service: ${client.service}`,
  `Package: ${client.packageName}`,
  `Budget: ${client.budget || 'Not provided'}`,
  `Start Date: ${client.startDate || 'Not provided'}`,
  `Kickoff Target: ${kickoffTarget}`,
  `Owner: ${owner}`,
  `Notes: ${client.notes || 'No notes'}`
].join('\n');

return [{
  json: {
    ...client,
    owner,
    duplicateFound: Boolean(duplicate),
    duplicateClientId: duplicate?.['Client ID'] || '',
    missingInfo: missing.join(', ') || 'None',
    priority,
    kickoffTarget,
    checklistItems: checklist.join('\n'),
    currentStage: duplicate ? 'Duplicate Review' : 'Ready for onboarding',
    riskLevel,
    needsAttention,
    riskReason: riskReasons.join(', ') || 'No risk detected',
    handoffSummary,
    recommendedAction: duplicate
      ? 'Review the existing client before creating another onboarding.'
      : needsAttention
        ? 'Project manager should review the client before kickoff.'
        : 'Proceed with standard onboarding.'
  }
}];

const now = new Date();
const rows = $input.all().map(item => item.json).filter(row => row['Project ID']);

const risky = rows.map(row => {
  const kickoff = row['Kickoff Target'] ? new Date(row['Kickoff Target']) : null;
  const created = row['Created At'] ? new Date(row['Created At']) : null;
  const daysSinceCreated = created ? Math.floor((now - created) / 86400000) : 0;
  const daysToKickoff = kickoff ? Math.ceil((kickoff - now) / 86400000) : null;
  const stage = String(row['Current Stage'] || '').toLowerCase();
  const riskLevel = String(row['Risk Level'] || '').toLowerCase();

  const reasons = [];
  if (daysToKickoff !== null && daysToKickoff < 0 && !stage.includes('complete')) reasons.push(`${Math.abs(daysToKickoff)} day(s) past kickoff target`);
  if (daysSinceCreated >= 5 && !stage.includes('complete')) reasons.push(`${daysSinceCreated} day(s) in onboarding`);
  if (riskLevel === 'high' || riskLevel === 'duplicate review') reasons.push(`Risk level: ${row['Risk Level']}`);

  return { row, reasons };
}).filter(item => item.reasons.length);

if (!risky.length) {
  return [{ json: { hasRisk: false, digest: 'No onboarding records need attention today.' } }];
}

const digest = risky.map(item => {
  const row = item.row;
  return `- ${row['Project ID']} | ${row['Client Name']} | ${row['Current Stage']} | ${item.reasons.join('; ')}`;
}).join('\n');

return [{
  json: {
    hasRisk: true,
    riskCount: risky.length,
    digest
  }
}];
